    let positive: Vec<&RegexMatcher> = ctx
        .plan
        .terms
        .iter()
        .zip(ctx.matchers)
        .filter(|(term, _)| term.modifier != Modifier::Excluded)
        .map(|(_, matcher)| matcher)
        .collect();
    let line_matches = |text: &str| positive.iter().any(|matcher| matches_text(matcher, text));
